/**
 * Arma el email del onboarding en un solo lugar.
 *
 * Está acá y no dentro del nodo de Brevo por una razón práctica: el día que
 * Pía quiera cambiar una frase, se edita este nodo y listo.
 *
 * 2026-08-18: se cayeron la llamada de bienvenida, la Semana 0 y la garantía
 * como promesa comercial. El mensaje empuja a entrenar el mismo día, que es lo
 * único que predice que una clienta termine el reto.
 * 2026-08-22: se cayó el brazo de WhatsApp (quedó fuera de la automatización) y
 * el disparador pasó a ser el webhook de MercadoPago. Como ahora la suscripción
 * se renueva sola, `acceso_vence` viene vacío en el plan mensual: la línea del
 * vencimiento sólo se escribe si la fila la trae.
 */
const cfg = $('Configuración').first().json;
const v = $input.first().json;

const nombreCorto = String(v.nombre ?? '').trim().split(/\s+/)[0] || '';
const saludo = nombreCorto ? `Hola ${nombreCorto}` : 'Hola';

const vence = String(v.acceso_vence ?? '').trim();
const lineaVence = vence
  ? `<p>Tu acceso está activo hasta el <strong>${vence}</strong>. Te aviso antes de que se venza.</p>`
  : '<p>Se renueva solo todos los meses, así que no tenés que hacer nada. Cancelás cuando quieras desde tu cuenta de MercadoPago.</p>';

const html = `
<p>${saludo},</p>
<p>Ya está confirmado tu pago. Tenés todo el material disponible desde ahora: no hay nada que esperar ni ningún grupo que arranque.</p>
<p><strong>Qué hacer hoy, en este orden:</strong></p>
<ol>
  <li><a href="${cfg.skoolInviteUrl}">Entrá a la comunidad</a> y presentate en el feed. Si te pide esperar aprobación, avisame y te abro en el momento.</li>
  <li><a href="${cfg.grupoWhatsappUrl}">Sumate al grupo de WhatsApp</a>.</li>
  <li>Mirá los videos de arranque. En 20 minutos sabés cómo funciona el método, cómo leer tu rutina y cómo mandarme un video para que te corrija la técnica.</li>
</ol>
<p>Y después, si podés, hacé la sesión 1 hoy. Las que entrenan el mismo día que entran son las que llegan al día 28.</p>
${lineaVence}
<p>Nos vemos adentro.<br>Pía</p>
`.trim();

return [{
  json: {
    ...v,
    nombreCorto,
    asuntoEmail: 'Estás adentro del Reto 28 Días',
    cuerpoEmail: html,
  },
}];

