parameters.jsCode:
// La fila de `comunidad` arranca en cero. Es el tablero de la métrica principal
// del negocio —la tasa de finalización— y A6 la recalcula todos los días.
//
// `fecha_inicio` reemplazó a `grupo` el 2026-08-18: sin cohortes no hay fecha de
// arranque compartida, así que el día del reto sólo se calcula contra el día en
// que entró ella.
//
// La clave pasó de `whatsapp` a `email` el 2026-08-22. Nuestro formulario de
// checkout pide nombre y email nada más, así que la columna `whatsapp` de
// `ventas` viene vacía y no sirve para cruzar nada.
const v = $('Armar el email').first().json;

return [{
  json: {
    alumna: v.nombre ?? '',
    email: v.email ?? '',
    whatsapp: v.whatsapp ?? '',
    fecha_inicio: new Date().toISOString().slice(0, 10),
    dia_actual: 0,
    ultimo_checkin: '',
    rutinas_completadas: 0,
    estado_riesgo: 'ok',
  },
}];

// Se marca «invitada» y no «sí»: el acceso lo completa ella cuando acepta la
// invitación de Skool. A30 levanta a las que quedan colgadas en este estado.
//
// Este es además el candado de idempotencia del flujo: mientras la fila diga
// «no», una notificación repetida de MercadoPago volvería a mandar el mail.
// Por eso este paso va último, cuando ya salió todo lo demás.
const v = $('Armar el email').first().json;

return [{
  json: {
    external_reference: v.external_reference,
    acceso_skool: 'invitada',
  },
}];
